class Prediction {
  final int predicted, decision;
  final List<double> posterior, logPosterior;
  final double confidence;
  Prediction(
    this.predicted,
    this.decision,
    this.posterior,
    this.logPosterior,
    this.confidence,
  );
}

int argmax(List<double> values) {
  var best = 0;
  for (var i = 1; i < values.length; i++) {
    if (values[i] > values[best]) best = i;
  }
  return best;
}

int argmin(List<double> values) {
  var best = 0;
  for (var i = 1; i < values.length; i++) {
    if (values[i] < values[best]) best = i;
  }
  return best;
}
  List<double> scores(List<double> v) {
    final q = squaredDistances(v);
    return [
      for (var k = 0; k < q.length; k++)
        logPriors[k] - normalizer - logDets[k] / 2 - q[k] / 2,
    ];
  }
  Prediction inferVector(List<double> v, [List<List<double>>? costs]) {
    final g = scores(v),
        pred = argmax(g),
        ex = [for (final score in g) math.exp(score - g[pred])];
    var total = 0.0;
    for (final x in ex) {
      total += x;
    }
    final probs = [for (final x in ex) x / total],
        lt = math.log(total),
        logs = [for (final x in g) (x - g[pred]) - lt];
    var decision = pred;
    if (costs != null) {
      final risks = List.filled(g.length, 0.0);
      for (var b = 0; b < g.length; b++) {
        for (var k = 0; k < g.length; k++) {
          risks[b] += probs[k] * costs[k][b];
        }
      }
      decision = argmin(risks);
    }
    return Prediction(pred, decision, probs, logs, probs[argmax(probs)]);
  }

  Prediction infer(List<double> values, [List<List<double>>? costs]) =>
      inferVector(vector(values), costs);
  Metrics(List<int> actual, List<int> predicted, int c)
    : matrix = List.generate(c, (_) => List.filled(c, 0)),
      support = List.filled(c, 0),
      recall = [],
      precision = [],
      f1 = [] {
    for (var i = 0; i < actual.length; i++) {
      matrix[actual[i]][predicted[i]]++;
    }
          rs = [
            for (final row in data.test) model.infer(row.values, data.costs),
          ];
      models.add(model);
      results.add(rs);
      predictions.add(rs.map((r) => r.predicted).toList());
  List<String> modelEvaluation(int k) {
    final rs = results[k],
        metrics = Metrics(testActual, predictions[k], c),
        lines = [
          'model ${modelNames[k]}',
          ...confusionLines(data.classes, metrics.matrix),
        ];
    for (var i = 0; i < m; i++) {
      final row = data.test[i], r = rs[i];
      loss += r.logPosterior[row.classIndex];
      if (r.predicted != row.classIndex) {
        errors.add(
          'error ${row.id} actual ${row.label} predicted ${data.classes[r.predicted]} confidence ${real(r.confidence)}',
        );
      }
    }
    for (final threshold in data.params.reject) {
      var count = 0, correct = 0;
      for (var i = 0; i < m; i++) {
        final r = rs[i];
        if (r.confidence >= threshold) {
          count++;
          if (r.predicted == testActual[i]) correct++;
        }
      }
      lines.add(
        'reject ${real(threshold)} accepted $count coverage ${ratio(count, m)} accuracy ${ratio(correct, count)}',
      );
    }
  List<int> ensemble() {
    final pred = <int>[];
    for (var i = 0; i < m; i++) {
      final p = List.filled(c, 0.0);
      for (var k = 0; k < c; k++) {
        for (var model = 0; model < 3; model++) {
          p[k] += results[model][i].posterior[k];
        }
        p[k] /= 3;
      }
      pred.add(argmax(p));
    }
    return pred;
  }
    for (var k = 0; k < 3; k++) {
      var total = 0.0, decision = 0.0;
      var changed = 0, correct = 0;
      for (var i = 0; i < m; i++) {
        final r = results[k][i], y = testActual[i];
        total += data.costs[y][r.predicted];
        decision += data.costs[y][r.decision];
        if (r.decision != r.predicted) changed++;
        if (r.decision == y) correct++;
      }
      lines.add(
        '${modelNames[k]} argmax_total ${real(total)} decision_total ${real(decision)} changed $changed decision_accuracy ${ratio(correct, m)}',
      );
    }
